    "표8_상담적용": [
        {"상황":"기적이 왜 오늘날에는 일어나지 않는지 의문을 가진 성도", "성경원리":"예수님의 기적은 메시아 증명이라는 특수한 목적을 가졌으며 오늘날에도 변화된 삶이라는 더 큰 기적이 계속되고 있습니다", "실제적용":"물리적 기적에만 집중하지 말고 복음을 통한 삶의 변화라는 지속적 기적에 주목하십시오"},
        {"상황":"자신의 사역이 하나님의 뜻인지 확신이 없는 사역자", "성경원리":"예수님의 사역이 아버지께서 주신 일이었듯이 우리의 사역도 하나님의 부르심과 은사에 근거해야 합니다", "실제적용":"하나님의 부르심을 재확인하고 그 사역의 열매를 통해 하나님의 인도하심을 분별하십시오"},
        {"상황":"기독교의 진리성에 대해 지적 의문을 가진 구도자", "성경원리":"예수님은 말뿐 아니라 사역으로 자신의 정체성을 증명하셨으며 이 증거들은 역사적으로 검증 가능합니다", "실제적용":"복음서에 기록된 예수님의 사역을 역사적 맥락에서 공부하며 그 증거의 신뢰성을 검토해 보십시오"}
    ],
    "표9_교차참조": [
        {"구절":"사 35:5-6", "연결점":"그 때에 소경의 눈이 밝을 것이며 귀먹은 자의 귀가 열릴 것이며 저는 자는 사슴같이 뛸 것이며", "구분":"구약"},
        {"구절":"사 61:1", "연결점":"주 여호와의 신이 내게 임하였으니 이는 여호와께서 내게 기름을 부으사 가난한 자에게 아름다운 소식을 전하게 하려 하심이라", "구분":"구약"},
        {"구절":"출 4:1-9", "연결점":"이 두 이적을 다 믿지 아니하거든 하수를 조금 취하여 육지에 부으라", "구분":"구약"},
        {"구절":"시 77:14", "연결점":"주는 기이한 일을 행하신 하나님이시라 열방 중에 주의 능력을 나타내셨나이다", "구분":"구약"},
        {"구절":"요 10:37-38", "연결점":"만일 내가 내 아버지의 일을 행치 아니하거든 나를 믿지 말려니와 내가 행하거든 나를 믿지 아니할지라도 그 일은 믿으라", "구분":"신약"},
        {"구절":"요 14:11", "연결점":"내가 아버지 안에 있고 아버지가 내 안에 계신 것을 믿으라 그렇지 못하겠거든 행하는 그 일을 인하여 나를 믿으라", "구분":"신약"},
        {"구절":"행 2:22", "연결점":"하나님께서 기사와 표적과 능력으로 너희 가운데서 그를 증거하셨느니라", "구분":"신약"},
        {"구절":"요 19:30", "연결점":"예수께서 신 포도주를 받으신 후 가라사대 다 이루었다 하시고 머리를 숙이시고 영혼이 돌아가시니라", "구분":"신약"}
    ]
